const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cuyuni = ee.Geometry.Point([-58.628264, 6.437929]).buffer(100);
  const confluence = ee.Geometry.Point([-58.606792, 6.407305]).buffer(100);
  const date = '2023-08-16';

  // 2. Data Acquisition - Sentinel-2 with cloud masking
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, '2023-08-17')
    .filterBounds(cuyuni.union(confluence));

  let img = s2.first();

  // Check for empty collection
  const collSize = s2.size().getInfo();
  if (collSize === 0) {
    // Try 3-day window
    const s2Wider = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate('2023-08-14', '2023-08-19')
      .filterBounds(cuyuni.union(confluence))
      .sort('CLOUDY_PIXEL_PERCENTAGE');

    img = s2Wider.first();
    const widerSize = s2Wider.size().getInfo();

    if (widerSize === 0) {
      console.log(`No Sentinel-2 images found for ${date} or ±3 days.`);
      console.log('<answer>C1</answer>');
      return;
    }
    console.log(`Using nearest cloud-free image (${widerSize} available)`);
  }

  // Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitBitMask).eq(0));
    return image.updateMask(mask);
  }

  const imgMasked = maskClouds(img);

  // Function to calculate brightness (average of visible bands)
  function calculateBrightness(image, geometry) {
    const visible = image.select(['B2', 'B3', 'B4']); // Blue, Green, Red
    const stats = visible.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 100,
      maxPixels: 1e9,
      bestEffort: true
    });

    // Get count of valid pixels
    const count = visible.select('B2').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 100,
      maxPixels: 1e9,
      bestEffort: true
    }).get('B2');

    return {stats: stats, count: count};
  }

  // Calculate brightness for both locations
  const cuyuniBright = calculateBrightness(imgMasked, cuyuni);
  const confluenceBright = calculateBrightness(imgMasked, confluence);

  const cuyuniCount = cuyuniBright.count.getInfo();
  const confluenceCount = confluenceBright.count.getInfo();

  console.log(`Cuyuni valid pixels: ${cuyuniCount}`);
  console.log(`Confluence valid pixels: ${confluenceCount}`);

  // Check for no valid pixels
  if (cuyuniCount === 0 || confluenceCount === 0) {
    console.log('One or both locations have no valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Get brightness values
  const cuyuniB2 = cuyuniBright.stats.get('B2').getInfo();
  const cuyuniB3 = cuyuniBright.stats.get('B3').getInfo();
  const cuyuniB4 = cuyuniBright.stats.get('B4').getInfo();

  const confluenceB2 = confluenceBright.stats.get('B2').getInfo();
  const confluenceB3 = confluenceBright.stats.get('B3').getInfo();
  const confluenceB4 = confluenceBright.stats.get('B4').getInfo();

  // Calculate average brightness (simple mean of visible bands)
  const cuyuniAvg = (cuyuniB2 + cuyuniB3 + cuyuniB4) / 3;
  const confluenceAvg = (confluenceB2 + confluenceB3 + confluenceB4) / 3;

  console.log(`Cuyuni brightness: ${cuyuniAvg.toFixed(4)}`);
  console.log(`Confluence brightness: ${confluenceAvg.toFixed(4)}`);

  // Validation checks
  if (cuyuniAvg === null || confluenceAvg === null || 
      isNaN(cuyuniAvg) || isNaN(confluenceAvg) ||
      cuyuniAvg < 0 || cuyuniAvg > 1 || 
      confluenceAvg < 0 || confluenceAvg > 1) {
    console.log('Invalid brightness values detected.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Determine answer based on brightness comparison
  if (cuyuniAvg > confluenceAvg) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
